const SEARCH_RENDER_TIMERS={};
function bindStableSearch(input,stateKey,renderFn,delay=220){
  if(!input)return;
  input.oninput=()=>{
    const value=input.value;
    ui[stateKey]=value;
    const start=input.selectionStart==null?value.length:input.selectionStart;
    const end=input.selectionEnd==null?start:input.selectionEnd;
    const id=input.id;
    const scrollY=window.scrollY;
    clearTimeout(SEARCH_RENDER_TIMERS[stateKey]);
    SEARCH_RENDER_TIMERS[stateKey]=setTimeout(()=>{
      renderFn();
      requestAnimationFrame(()=>{
        const next=document.getElementById(id);
        if(!next)return;
        try{next.focus({preventScroll:true})}catch(_e){next.focus()}
        const max=next.value.length;
        try{next.setSelectionRange(Math.min(start,max),Math.min(end,max))}catch(_e){}
        window.scrollTo(0,scrollY);
      });
    },delay);
  };
  input.onkeydown=e=>{
    if(e.key==='Escape'){
      clearTimeout(SEARCH_RENDER_TIMERS[stateKey]);
      input.value=''; ui[stateKey]=''; renderFn();
    }
  };
}
