function mfParse(v){let s=String(v??'').trim().replace(/\s/g,'');if(!s)return 0;if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');const n=Number(s.replace(/[^0-9.\-]/g,''));return Number.isFinite(n)?n:0}

function mfParseWebNumber(v){let s=String(v??'').trim().replace(/\s/g,'').replace(/[^0-9,.-]/g,'');if(!s)return 0;const comma=s.lastIndexOf(','),dot=s.lastIndexOf('.');if(comma>=0&&dot>=0){if(dot>comma)s=s.replace(/,/g,'');else s=s.replace(/\./g,'').replace(',','.')}else if(comma>=0){const tail=s.length-comma-1;s=tail>=1&&tail<=4?s.replace(',','.'):s.replace(/,/g,'')}else if(dot>=0){const tail=s.length-dot-1;if(tail===3&&s.indexOf('.')===dot&&Number(s.slice(0,dot))>=10)s=s.replace(/\./g,'')}const n=Number(s);return Number.isFinite(n)?n:0}
function mfDateFromText(txt){const iso=String(txt||'').match(/(?:as of|per tanggal(?:\s+as of)?)\s*(\d{4}-\d{2}-\d{2})/i);if(iso)return iso[1];const en=String(txt||'').match(/\b(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(20\d{2})\b/i);if(en){const map={jan:'01',feb:'02',mar:'03',apr:'04',may:'05',jun:'06',jul:'07',aug:'08',sep:'09',oct:'10',nov:'11',dec:'12'};return `${en[3]}-${map[en[2].slice(0,3).toLowerCase()]}-${pad2(en[1])}`}const id=String(txt||'').match(/\b(\d{1,2})\s+(Januari|Februari|Maret|April|Mei|Juni|Juli|Agustus|September|Oktober|November|Desember)\s+(20\d{2})\b/i);if(id){const map={januari:'01',februari:'02',maret:'03',april:'04',mei:'05',juni:'06',juli:'07',agustus:'08',september:'09',oktober:'10',november:'11',desember:'12'};return `${id[3]}-${map[id[2].toLowerCase()]}-${pad2(id[1])}`}return''}
function mfExtractNav(txt,parser){const t=String(txt||'');let m=null;if(parser==='mandiri')m=t.match(/([0-9][0-9.,]*)\s+IDR\s+NAB\/Unit/i)||t.match(/NAB\/Unit(?:\s+NAV\/Unit)?[\s\S]{0,120}?([0-9][0-9.,]*)\s*IDR/i);else if(parser==='bareksa')m=t.match(/Nilai Aktiva Bersih\/Unit[\s\S]{0,120}?([0-9][0-9.,]*)\s*IDR/i)||t.match(/NAB\/Unit[\s\S]{0,120}?([0-9][0-9.,]*)/i);else if(parser==='bca')m=t.match(/NAB\/Unit[\s\S]{0,100}?([0-9][0-9.,]*)/i);else if(parser==='bankmandiri'){const block=(t.match(/SCHRODER SYARIAH BALANCED FUND[\s\S]{0,1600}/i)||[])[0]||'';m=block.match(/(?:NAB\/Unit|NAV\/Unit|Nilai Aktiva Bersih\/Unit)[\s\S]{0,120}?([0-9][0-9.,]*)/i)}if(!m&&parser!=='bankmandiri')m=t.match(/(?:NAB\/Unit|Nilai Aktiva Bersih\/Unit)[\s\S]{0,150}?([0-9][0-9.,]*)/i);const nav=m?mfParseWebNumber(m[1]):0;return nav>500&&nav<100000?nav:0}
async function mfFetchPublicPage(url){const reader='https://r.jina.ai/'+url;const res=await fetch(reader,{cache:'no-store',headers:{'Accept':'text/plain'}});if(!res.ok)throw new Error(`HTTP ${res.status}`);const txt=await res.text();if(!txt||txt.length<80)throw new Error('Respons kosong');return txt}
async function mfFetchOneFund(f){const sources=MUTUAL_FUND_ONLINE_SOURCES[f.id]||[];let lastErr='';for(const s of sources){try{const txt=await mfFetchPublicPage(s.url),nav=mfExtractNav(txt,s.parser);if(!nav)throw new Error('NAB tidak terbaca');return{nav,source:s.name,date:mfDateFromText(txt)||new Date().toISOString().slice(0,10)}}catch(e){lastErr=`${s.name}: ${e.message||e}`}}throw new Error(lastErr||'Tidak ada sumber online')}
function mfSyncAgeHours(){const t=Number(state.mutualFundUpdatedAt)||0;return t?((Date.now()-t)/36e5):9999}
async function syncMutualFundsOnline(showNotice=true){if(MF_SYNC_IN_PROGRESS)return;MF_SYNC_IN_PROGRESS=true;const btn=document.getElementById('syncOnlineMF');if(btn){btn.classList.add('syncing');btn.innerHTML=`${uiSvg('summary')} Sinkronisasi…`}const results=[];for(const f of (state.mutualFunds||[])){if(!MUTUAL_FUND_ONLINE_SOURCES[f.id])continue;try{const x=await mfFetchOneFund(f);f.currentNav=x.nav;f.priceSource=x.source;f.priceDate=x.date;results.push({ok:true,id:f.id,name:f.name,...x})}catch(e){results.push({ok:false,id:f.id,name:f.name,error:String(e.message||e)})}}const ok=results.filter(x=>x.ok),failed=results.filter(x=>!x.ok);state.mutualFundUpdatedAt=Date.now();state.mutualFundUpdated=failed.length?`Online · ${new Date().toLocaleString('id-ID')} · ${ok.length}/${results.length} produk · ${failed.length} perlu manual`:`Online · ${new Date().toLocaleString('id-ID')} · ${ok.length}/${results.length} produk`;syncMutualFundAssetValue(ui.budgetYear,ui.budgetMonth);recalcFinancialMonth(ui.budgetYear,ui.budgetMonth);saveState();MF_SYNC_IN_PROGRESS=false;if(document.getElementById('view'))renderBudget();if(showNotice&&failed.length){setTimeout(()=>manualMutualFundUpdateModal(failed.map(x=>x.id),`Sync otomatis berhasil ${ok.length}/${results.length}. Isi manual produk yang gagal.`),0)}}
function manualMutualFundUpdateModal(ids=[],message=''){const all=state.mutualFunds||[],wanted=Array.isArray(ids)&&ids.length?new Set(ids):null,funds=wanted?all.filter(f=>wanted.has(f.id)):all;if(!funds.length)return;const today=new Date().toISOString().slice(0,10);openModal(`<h3>Update NAB Manual</h3><div class="hierarchyhint">${message?esc(message)+' ':''}Gunakan nilai dari <b>Livin’ by Mandiri</b>. Isi salah satu: <b>NAB/Unit</b> atau <b>Nilai Saat Ini</b>. Jika Nilai Saat Ini diisi, NAB dihitung otomatis dari jumlah unit.</div><div class="mf-manual-editor"><div class="mf-manual-head"><span>Produk</span><span>NAB / Unit</span><span>Nilai Saat Ini</span><span>Tanggal</span></div>${funds.map(f=>`<div class="mf-manual-row" data-id="${esc(f.id)}"><div><b>${esc(f.name)}</b><small>${mfFmtQty(f.units||0)} unit</small></div><input class="mfmNav" value="${Number(f.currentNav)>0?mfFmtNav(f.currentNav):''}" inputmode="decimal" placeholder="0"><input class="mfmValue" value="${mutualFundCurrentValue(f)>0?finFormat(mutualFundCurrentValue(f)):''}" inputmode="decimal" placeholder="0"><input class="mfmDate" type="date" value="${esc(f.priceDate||today)}"></div>`).join('')}</div><div class="modalactions"><button class="btn ghost" id="mfManualCancel">Batal</button><button class="btn" id="mfManualSave">Simpan Manual</button></div>`);document.getElementById('mfManualCancel').onclick=closeModal;document.getElementById('mfManualSave').onclick=()=>{let changed=0;document.querySelectorAll('.mf-manual-row').forEach(row=>{const f=all.find(x=>x.id===row.dataset.id);if(!f)return;const nav=mfParse(row.querySelector('.mfmNav').value),value=finParse(row.querySelector('.mfmValue').value),date=row.querySelector('.mfmDate').value||today,units=Number(f.units)||0;let finalNav=nav;if(value>0&&units>0)finalNav=value/units;if(finalNav>0){f.currentNav=finalNav;f.priceSource="Livin' by Mandiri · Manual";f.priceDate=date;changed++}});if(!changed)return alert('Isi minimal satu NAB/Unit atau Nilai Saat Ini.');state.mutualFundUpdatedAt=Date.now();state.mutualFundUpdated=`Manual Livin’ · ${new Date().toLocaleString('id-ID')} · ${changed} produk`;syncMutualFundAssetValue(ui.budgetYear,ui.budgetMonth);recalcFinancialMonth(ui.budgetYear,ui.budgetMonth);saveState();closeModal();renderBudget()}}

function maybeAutoSyncMutualFunds(){if(MF_SYNC_IN_PROGRESS)return;if(mfSyncAgeHours()>=6)setTimeout(()=>syncMutualFundsOnline(false),250)}
function mfFmtQty(n){return Number(n||0).toLocaleString('id-ID',{minimumFractionDigits:4,maximumFractionDigits:4})}
function mfFmtNav(n){return Number(n||0)>0?Number(n).toLocaleString('id-ID',{minimumFractionDigits:4,maximumFractionDigits:4}):'—'}
function mutualFundBuyValue(f){const explicit=Number(f?.buyValue)||0;if(explicit>0)return explicit;return (Number(f?.units)||0)*(Number(f?.buyNav)||0)}
function mutualFundCurrentValue(f){return (Number(f?.units)||0)*(Number(f?.currentNav)||0)}
function mutualFundTotals(){const funds=state.mutualFunds||[];return funds.reduce((o,f)=>{o.buy+=mutualFundBuyValue(f);o.current+=mutualFundCurrentValue(f);return o},{buy:0,current:0})}
function syncMutualFundAssetValue(y,m){const now=new Date(),isCurrent=y===now.getFullYear()&&m===now.getMonth()+1,total=mutualFundTotals().current;if(!isCurrent||total<=0)return;const rows=state.rawMonthly?.[finKey(y,m)]||[];const r=rows.find(x=>x.section==='asset'&&String(x.label||'').startsWith('Reksadana'));if(r)r.budget=Math.round(total)}
function normalizeBudgetMatchText(s){return String(s||'').toLowerCase().replace(/\d{1,2}\/\d{1,2}/g,' ').replace(/(sb|sp|gopay|mandiri|jenius|bca|seabank|shopeepay)\s*:?/g,' ').replace(/[^a-z0-9]+/g,' ').trim()}
