SEED.budget.forEach(r=>{if(r.year>=2026&&r.year<=2030&&!r.isTotal&&r.sourceRow!=null){const key=`${r.year}-${r.month}-${r.sourceRow}`;FIN_BUDGET_INDEX_BY_ROW[key]=Number(r.budget)||0;const tkey=`${r.year}-${r.month}-${r.category}|${normalizeBudgetMatchText(r.component)}`;if(!(tkey in FIN_BUDGET_INDEX_BY_TEXT))FIN_BUDGET_INDEX_BY_TEXT[tkey]=Number(r.budget)||0;}});
function syncFinancialBudgetForMonth(y,m){const rows=state.rawMonthly[finKey(y,m)]||[];rows.forEach(r=>{if(r.kind==='detail'){const rowKey=`${y}-${m}-${r.sourceRow}`;let b=(rowKey in FIN_BUDGET_INDEX_BY_ROW)?FIN_BUDGET_INDEX_BY_ROW[rowKey]:null;if((b===null||b===undefined) && r.category){const tx=normalizeBudgetMatchText(String(r.rawLabel||r.label||'').split(';')[0]);const textKey=`${y}-${m}-${r.category}|${tx}`;if(textKey in FIN_BUDGET_INDEX_BY_TEXT)b=FIN_BUDGET_INDEX_BY_TEXT[textKey];}if(!r.budgetEdited&&(r.budget==null||Number(r.budget)===0) && b!=null && !Number.isNaN(Number(b)))r.budget=Number(b)||0;}})}
