function normalizeFinancialSections(){const assetCats=new Set(['Aset','Piutang']);const assetWords=/(antam|ubs|emas|logam mulia|schroder|reksadana|sunlife|deposito|piutang)/i;Object.values(state.rawMonthly||{}).forEach(rows=>{(rows||[]).forEach(r=>{const txt=`${r.category||''} ${r.label||''}`;if(assetCats.has(r.category)||assetCats.has(r.label)||assetWords.test(txt)){r.section='asset';if(r.kind==='category'&&r.label==='Piutang')r.category='Piutang';if(r.kind==='category'&&r.label==='Aset')r.category='Aset';}})})}
