function receivableParseAmount(text,fallback=0){const nums=String(text||'').match(/(?:^|\s)(\d{4,})(?=\s|$)/g)||[];if(nums.length){const n=Number(nums[nums.length-1].trim());if(Number.isFinite(n)&&n>0)return n}return Number(fallback)||0}
function receivablePaid(r){return (r.payments||[]).reduce((s,p)=>s+(Number(p.amount)||0),0)}
function receivableRemaining(r){return Math.max(0,(Number(r.principal)||0)-receivablePaid(r))}
function receivableStatus(r){return receivableRemaining(r)<=0?'paid':'active'}
function ensureReceivableModelV32(){if(state.receivableModelVersion===32&&Array.isArray(state.receivables))return;state.receivables=[
{id:'recv-ipit-2026',sourceKey:null,sourceRowId:null,sourceMonth:6,year:2026,month:6,date:'09/06',description:'Ipit',principal:1800000,installmentCount:6,installmentAmount:300000,payments:[],customized:true,createdAt:Date.now()},
{id:'recv-dini-2026',sourceKey:null,sourceRowId:null,sourceMonth:8,year:2026,month:8,date:'02/08',description:'Mba Dini',principal:5000000,installmentCount:5,installmentAmount:1000000,payments:[],customized:true,createdAt:Date.now()+1}
];state.receivableDeletedKeys=[];state.receivableModelVersion=32;saveState()}
function ensureReceivableLedger(year,month){ensureReceivableModelV32();return (state.receivables||[]).filter(r=>Number(r.year)===Number(year)&&Number(r.month)<=Number(month))}
function receivableTotals(year,month){const list=ensureReceivableLedger(year,month);return list.reduce((o,r)=>{o.principal+=Number(r.principal)||0;o.paid+=receivablePaid(r);o.remaining+=receivableRemaining(r);o.active+=receivableStatus(r)==='active'?1:0;o.settled+=receivableStatus(r)==='paid'?1:0;return o},{principal:0,paid:0,remaining:0,active:0,settled:0})}
function receivablePlanText(r){const count=Number(r.installmentCount)||0,amt=Number(r.installmentAmount)||0;if(count>0&&amt>0)return `${count}x @ ${finFormat(amt)}`;if(count>0)return `${count}x cicilan`;if(amt>0)return `@ ${finFormat(amt)}`;return 'Belum diatur'}
function receivablePaidInstallments(r){const count=Number(r.installmentCount)||0,amt=Number(r.installmentAmount)||0,paid=receivablePaid(r);if(count>0&&amt>0)return Math.min(count,Math.floor((paid+0.01)/amt));return (r.payments||[]).length}
function renderPiutangRows(year,month){const list=ensureReceivableLedger(year,month).sort((a,b)=>a.month-b.month||String(a.date||'').localeCompare(String(b.date||''))),tot=receivableTotals(year,month);const rows=list.map(r=>{const remaining=receivableRemaining(r),status=receivableStatus(r),paidN=receivablePaidInstallments(r),count=Number(r.installmentCount)||0,plan=receivablePlanText(r);return `<tr data-recv="${esc(r.id)}"><td>${esc(r.date||'—')}</td><td><select class="receivable-source-select" data-id="${esc(r.id)}">${transactionSourceOptions(r.transactionSource||'',true)}</select></td><td><div class="piutang-name">${esc(r.description||'Piutang')}${status==='paid'?'<span class="piutang-lunas">Lunas</span>':''}</div><div class="piutang-plan">${esc(plan)}${count?` · terbayar <b>${paidN}/${count}</b>`:''}</div></td><td class="piutang-value">${finFormat(remaining)}</td><td><div class="piutang-actions"><button class="record-action-btn edit edit-receivable" data-id="${esc(r.id)}" title="Edit piutang & rencana cicilan">${uiSvg('edit')}</button><button class="piutang-update pay-receivable" data-id="${esc(r.id)}" title="Update cicilan yang sudah dibayar" ${status==='paid'?'disabled':''}>${uiSvg('plus')}</button><button class="record-action-btn delete delete-receivable" data-id="${esc(r.id)}" title="Hapus piutang">${uiSvg('trash')}</button></div></td></tr>`}).join('');return `<div class="asset-tablewrap"><table class="piutang-simple-table"><colgroup><col class="piutang-date"><col class="piutang-source"><col><col class="piutang-value"><col class="piutang-action"></colgroup><thead><tr><th>Tanggal</th><th>Sumber</th><th>Uraian</th><th>Sisa Piutang</th><th>Aksi</th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="empty">Belum ada piutang aktif.</td></tr>'}${list.length?`<tr class="piutang-total"><td></td><td></td><td class="piutang-name">Total Sisa Piutang</td><td class="piutang-value">${finFormat(tot.remaining)}</td><td></td></tr>`:''}</tbody></table></div>`}

function findReceivable(id){ensureReceivableModelV32();return (state.receivables||[]).find(r=>r.id===id)}
function createReceivableRawRow(r){const key=finKey(r.year,r.month),rows=state.rawMonthly[key]||(state.rawMonthly[key]=[]);let insertAt=rows.findIndex(x=>x.label==='Total Expenditure');const catIdx=rows.findIndex(x=>x.kind==='category'&&x.label==='Piutang');if(catIdx>=0){const next=rows.findIndex((x,i)=>i>catIdx&&(x.kind==='category'||x.label==='Total Expenditure'));insertAt=next>=0?next:rows.length}if(insertAt<0)insertAt=rows.length;const raw={id:uid('rawpiutang'),sourceRow:null,label:composeDateRecord(r.date,r.description),rawLabel:composeDateRecord(r.date,r.description),budget:Number(r.principal)||0,actual:0,transactionSource:r.transactionSource||'',sourceAmount:null,sourceColor:'manual',kind:'detail',section:'asset',category:'Piutang'};rows.splice(insertAt,0,raw);r.sourceRowId=raw.id;r.sourceMonth=r.month;return raw}
function syncReceivableRawRow(r){if(!r?.sourceRowId)return;const rows=state.rawMonthly[finKey(r.year,r.sourceMonth||r.month)]||[],raw=rows.find(x=>x.id===r.sourceRowId);if(raw){raw.label=composeDateRecord(r.date,r.description);raw.rawLabel=raw.label;raw.budget=Number(r.principal)||0;raw.actual=0;raw.transactionSource=r.transactionSource||raw.transactionSource||''}}
