function copyRowsTo(rows,ty,monthMap=null){let updated=0,added=0;for(const r of rows){const tm=monthMap?monthMap(r.month):r.month;const candidates=state.budget.filter(x=>x.year===ty&&x.month===tm&&x.section===r.section&&x.category===r.category&&x.isTotal===r.isTotal);let target=null;if(r.sourceRow&&ty===r.year)target=candidates.find(x=>x.sourceRow===r.sourceRow);if(!target)target=candidates.find(x=>x.component===r.component);if(target){target.budget=r.budget;target.actual=r.actual;target.recurring=r.recurring;target.note=target.note||r.note;updated++}else{state.budget.push({...clone(r),id:uid('copy'),year:ty,month:tm,source:'Manual',sourceRow:null,isTotal:false,note:`Disalin dari ${MONTHS[r.month-1]} ${r.year}${r.note?' · '+r.note:''}`});added++}}return{updated,added}}
function copyMonthModal(){const sy=ui.budgetYear,sm=ui.budgetMonth;openModal(`<h3>Salin Budget Bulan</h3><div class="note" style="margin-bottom:12px">Sumber: <b>${MONTHS[sm-1]} ${sy}</b>. Nilai akan digabungkan ke komponen yang namanya sama di bulan tujuan; komponen baru ditambahkan bila belum ada.</div><div class="formgrid"><div class="field"><label>Tahun tujuan</label><select id="copyY">${[2026,2027,2028,2029,2030].map(y=>`<option ${y===sy?'selected':''}>${y}</option>`).join('')}</select></div><div class="field"><label>Bulan tujuan</label><select id="copyM">${MONTHS.map((m,i)=>`<option value="${i+1}" ${i+1===Math.min(12,sm+1)?'selected':''}>${m}</option>`).join('')}</select></div></div><div class="modalactions"><button class="btn ghost" id="mCancel">Batal</button><button class="btn" id="doCopy">Salin</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.getElementById('doCopy').onclick=()=>{const ty=+document.getElementById('copyY').value,tm=+document.getElementById('copyM').value;const rows=state.budget.filter(r=>r.year===sy&&r.month===sm);const res=copyRowsTo(rows,ty,()=>tm);saveState();ui.budgetYear=ty;ui.budgetMonth=tm;closeModal();alert(`Selesai: ${res.updated} komponen diperbarui, ${res.added} komponen baru ditambahkan.`);renderBudget()}}
function copyYearModal(){const sy=ui.budgetYear;openModal(`<h3>Salin Budget Tahun</h3><div class="note" style="margin-bottom:12px">Menyalin nilai ${sy} ke tahun tujuan dengan pencocokan kategori + nama komponen. Data awal pada tahun tujuan tidak diduplikasi.</div><div class="field"><label>Tahun tujuan</label><select id="copyY">${[2026,2027,2028,2029,2030].filter(y=>y!==sy).map(y=>`<option>${y}</option>`).join('')}</select></div><div class="modalactions"><button class="btn ghost" id="mCancel">Batal</button><button class="btn" id="doCopy">Salin</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.getElementById('doCopy').onclick=()=>{const ty=+document.getElementById('copyY').value;const rows=state.budget.filter(r=>r.year===sy);const res=copyRowsTo(rows,ty);saveState();ui.budgetYear=ty;closeModal();alert(`Selesai: ${res.updated} komponen diperbarui, ${res.added} komponen baru ditambahkan.`);renderBudget()}}

function renderHistory(){const el=document.getElementById('view');const years=Array.from({length:10},(_,i)=>2016+i);let sum=state.historySummary.filter(r=>r.year===ui.historyYear&&(ui.historyMonth===0||r.month===ui.historyMonth));let det=state.historyDetail.filter(r=>r.year===ui.historyYear&&(ui.historyMonth===0||r.month===ui.historyMonth)&&(`${r.category} ${r.note||''}`.toLowerCase().includes(ui.historySearch.toLowerCase())));const exp=sum.reduce((s,r)=>s+(Number(r.expense)||0),0),inc=sum.reduce((s,r)=>s+(Number(r.income)||0),0);el.innerHTML=`<div class="controls"><div class="control"><label>Tahun</label><select class="select" id="histYear">${years.map(y=>`<option ${y===ui.historyYear?'selected':''}>${y}</option>`).join('')}</select></div><div class="control"><label>Bulan</label><select class="select" id="histMonth"><option value="0">Semua bulan</option>${MONTHS.map((m,i)=>`<option value="${i+1}" ${ui.historyMonth===i+1?'selected':''}>${m}</option>`).join('')}</select></div><div class="control grow"><label>Cari komponen</label><input class="input" id="histSearch" value="${esc(ui.historySearch)}" placeholder="Cari kategori riwayat..."></div><button class="btn" id="addHistDetail">+ Tambah Komponen</button></div><div class="kpis"><div class="kpi" style="--accent:var(--orange)"><div class="label">Pengeluaran Tercatat</div><div class="value">${short(exp)}</div></div><div class="kpi"><div class="label">Pemasukan Tercatat</div><div class="value">${inc?short(inc):'—'}</div></div><div class="kpi"><div class="label">Komponen Detail</div><div class="value">${det.length}</div><div class="foot">Detail kategori tersedia terutama 2020+</div></div><div class="kpi" style="--accent:#F85525"><div class="label">Periode</div><div class="value">${ui.historyMonth?MONTHS[ui.historyMonth-1]+' ':''}${ui.historyYear}</div></div></div><div class="card"><div class="cardhead"><h2>Ringkasan Bulanan</h2><span class="tag">${ui.historyYear}</span></div><div class="historygrid">${MONTHS.map((m,i)=>{const r=state.historySummary.find(x=>x.year===ui.historyYear&&x.month===i+1);return `<div class="monthtile"><b>${m}</b><div class="v">${r&&r.expense!=null?short(r.expense):'—'}</div><div class="s">${r&&r.income!=null?'In '+short(r.income):'Pemasukan —'}</div>${r?`<button class="iconbtn edit-histsum" data-id="${r.id}" title="Edit ringkasan">✎</button>`:''}</div>`}).join('')}</div><div class="note">Untuk periode lama yang sumbernya tidak memiliki total bulanan yang dapat diringkas dengan aman, nilai ditampilkan “—” dan tetap dapat diisi manual.</div></div><div class="card"><div class="cardhead"><h2>Detail Kategori</h2><span class="tag">${det.length} record</span></div><div class="tablewrap"><table><thead><tr><th>Periode</th><th>Kategori</th><th class="num">Nilai</th><th>Catatan</th><th>Sumber</th><th>Aksi</th></tr></thead><tbody>${det.length?det.sort((a,b)=>a.month-b.month||a.category.localeCompare(b.category)).map(r=>`<tr><td>${MONTHS[r.month-1]} ${r.year}</td><td>${esc(r.category)}</td><td class="num">${fmt(r.amount)}</td><td>${esc(r.note||'')}</td><td><span class="badge asset">${esc((r.source&&r.source!=='AW-3')?r.source:'Import')}</span></td><td><button class="iconbtn edit-histdet" data-id="${r.id}">✎</button><button class="iconbtn del-histdet" data-id="${r.id}">⌫</button></td></tr>`).join(''):`<tr><td colspan="6" class="empty">Belum ada detail kategori untuk filter ini.</td></tr>`}</tbody></table></div></div>`;document.getElementById('histYear').onchange=e=>{ui.historyYear=+e.target.value;renderHistory()};document.getElementById('histMonth').onchange=e=>{ui.historyMonth=+e.target.value;renderHistory()};bindStableSearch(document.getElementById('histSearch'),'historySearch',renderHistory);document.getElementById('addHistDetail').onclick=()=>historyDetailModal();document.querySelectorAll('.edit-histdet').forEach(b=>b.onclick=()=>historyDetailModal(state.historyDetail.find(x=>x.id===b.dataset.id)));document.querySelectorAll('.del-histdet').forEach(b=>b.onclick=()=>{const r=state.historyDetail.find(x=>x.id===b.dataset.id);if(r&&confirm(`Hapus ${r.category} ${MONTHS[r.month-1]} ${r.year}?`)){state.historyDetail=state.historyDetail.filter(x=>x.id!==r.id);saveState();renderHistory()}});document.querySelectorAll('.edit-histsum').forEach(b=>b.onclick=()=>historySummaryModal(state.historySummary.find(x=>x.id===b.dataset.id)))}
function historyDetailModal(r=null){const x=r||{year:ui.historyYear,month:ui.historyMonth||1,category:state.categories.find(c=>c.type==='expense')?.name||'Biaya Rumah Tangga',amount:0,note:'',source:'Manual'};openModal(`<h3>${r?'Edit':'Tambah'} Komponen Riwayat</h3><div class="formgrid"><div class="field"><label>Tahun</label><select id="hy">${Array.from({length:10},(_,i)=>2016+i).map(y=>`<option ${y===x.year?'selected':''}>${y}</option>`).join('')}</select></div><div class="field"><label>Bulan</label><select id="hm">${MONTHS.map((m,i)=>`<option value="${i+1}" ${i+1===x.month?'selected':''}>${m}</option>`).join('')}</select></div><div class="field"><label>Kategori</label><select id="hc">${state.categories.map(c=>`<option ${c.name===x.category?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Nilai</label><input id="ha" type="number" value="${x.amount||0}"></div><div class="field full"><label>Catatan</label><textarea id="hn">${esc(x.note||'')}</textarea></div></div><div class="modalactions"><button class="btn ghost" id="mCancel">Batal</button><button class="btn" id="mSave">Simpan</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.getElementById('mSave').onclick=()=>{const o={id:r?r.id:uid('hist'),year:+document.getElementById('hy').value,month:+document.getElementById('hm').value,category:document.getElementById('hc').value,amount:valNum(document.getElementById('ha').value),note:document.getElementById('hn').value.trim(),source:r?r.source:'Manual'};if(r)Object.assign(r,o);else state.historyDetail.push(o);saveState();closeModal();renderHistory()}}
function historySummaryModal(r){openModal(`<h3>Edit Ringkasan ${MONTHS[r.month-1]} ${r.year}</h3><div class="formgrid"><div class="field"><label>Pengeluaran</label><input id="he" type="number" value="${r.expense??''}"></div><div class="field"><label>Pemasukan</label><input id="hi" type="number" value="${r.income??''}"></div><div class="field"><label>Saldo/Tabungan</label><input id="hs" type="number" value="${r.saving??''}"></div><div class="field full"><label>Catatan</label><textarea id="hn">${esc(r.note||'')}</textarea></div></div><div class="modalactions"><button class="btn ghost" id="mCancel">Batal</button><button class="btn" id="mSave">Simpan</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.getElementById('mSave').onclick=()=>{const cv=id=>document.getElementById(id).value.trim()===''?null:valNum(document.getElementById(id).value);r.expense=cv('he');r.income=cv('hi');r.saving=cv('hs');r.note=document.getElementById('hn').value.trim();saveState();closeModal();renderHistory()}}
function renderCategories(){const el=document.getElementById('view');const q=ui.categorySearch.toLowerCase();const cats=state.categories.filter(c=>c.name.toLowerCase().includes(q));el.innerHTML=`<div class="card"><div class="cardhead"><h2>Master Kategori</h2><button class="btn" id="addCat">+ Tambah Kategori</button></div><div class="controls"><div class="control grow"><label>Cari kategori</label><input class="input" id="catSearch" value="${esc(ui.categorySearch)}" placeholder="Cari..."></div></div><div class="categorylist">${cats.map(c=>{const n=state.budget.filter(r=>r.category===c.name).length+state.historyDetail.filter(r=>r.category===c.name).length;return `<div class="catitem"><div class="catname"><span class="dot" style="background:${c.color}"></span><span>${esc(c.name)}</span></div><div>${markType(c.type)}</div><div><button class="iconbtn edit-cat" data-id="${c.id}">✎</button><button class="iconbtn del-cat" data-id="${c.id}" ${n?'title="Kategori masih dipakai"':''}>⌫</button><div class="muted" style="font-size:9px">${n} record</div></div></div>`}).join('')}</div><div class="note">Mengubah nama kategori akan ikut memperbarui semua record budget dan riwayat yang memakai kategori tersebut.</div></div>`;bindStableSearch(document.getElementById('catSearch'),'categorySearch',renderCategories);document.getElementById('addCat').onclick=()=>categoryModal();document.querySelectorAll('.edit-cat').forEach(b=>b.onclick=()=>categoryModal(state.categories.find(x=>x.id===b.dataset.id)));document.querySelectorAll('.del-cat').forEach(b=>b.onclick=()=>{const c=state.categories.find(x=>x.id===b.dataset.id);const n=state.budget.filter(r=>r.category===c.name).length+state.historyDetail.filter(r=>r.category===c.name).length;if(n)return alert('Kategori masih dipakai oleh '+n+' record. Pindahkan record terlebih dahulu.');if(confirm('Hapus kategori '+c.name+'?')){state.categories=state.categories.filter(x=>x.id!==c.id);saveState();renderCategories()}})}
function categoryModal(c=null){const x=c||{name:'',type:'expense',color:'#0f766e'};openModal(`<h3>${c?'Edit':'Tambah'} Kategori</h3><div class="formgrid"><div class="field full"><label>Nama</label><input id="cn" value="${esc(x.name)}"></div><div class="field"><label>Jenis</label><select id="ct"><option value="income" ${x.type==='income'?'selected':''}>Pemasukan</option><option value="expense" ${x.type==='expense'?'selected':''}>Pengeluaran</option><option value="asset" ${x.type==='asset'?'selected':''}>Aset/Saldo</option></select></div><div class="field"><label>Warna</label><input id="cc" type="color" value="${x.color}"></div></div><div class="modalactions"><button class="btn ghost" id="mCancel">Batal</button><button class="btn" id="mSave">Simpan</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.getElementById('mSave').onclick=()=>{const name=document.getElementById('cn').value.trim();if(!name)return alert('Nama kategori wajib diisi.');if(state.categories.some(z=>z.name.toLowerCase()===name.toLowerCase()&&(!c||z.id!==c.id)))return alert('Nama kategori sudah ada.');if(c&&name!==c.name){state.budget.forEach(r=>{if(r.category===c.name)r.category=name});state.historyDetail.forEach(r=>{if(r.category===c.name)r.category=name})}if(c){c.name=name;c.type=document.getElementById('ct').value;c.color=document.getElementById('cc').value}else state.categories.push({id:uid('cat'),name,type:document.getElementById('ct').value,color:document.getElementById('cc').value});saveState();closeModal();renderCategories()}}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}
function csvEscape(v){const s=String(v??'');return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function renderBackup(){const el=document.getElementById('view');el.innerHTML=`<div class="grid2"><div class="card"><div class="cardhead"><h2>Backup & Restore</h2><span class="tag">Disarankan berkala</span></div><div class="split"><button class="btn" id="exportJson">Download Backup JSON</button><label class="btn ghost" style="display:inline-flex;align-items:center;cursor:pointer">Import Backup<input class="sr-only" id="importJson" type="file" accept="application/json,.json"></label><button class="btn ghost" id="exportCsv">Export Budget CSV</button></div><div class="note">Backup JSON mengunduh snapshot data Firestore yang sedang aktif. CSV mengekspor seluruh komponen budget 2026–2030.</div></div><div class="card"><div class="cardhead"><h2>Cakupan Data</h2><span class="tag">Cloud Firestore</span></div><div class="cloud-banner">Akun: <b>${esc(fb.user?.email||fb.user?.uid||'—')}</b> · Database: <b>${esc(savedFirebaseConfig()?.projectId||'—')}</b></div><div class="sourcebox"><div><small>Perencanaan</small><b>${esc(state.sourceMeta.budgetYears)}</b></div><div><small>Riwayat</small><b>${esc(state.sourceMeta.historyYears)}</b></div></div><div class="split" style="margin-top:12px"><button class="btn ghost" id="cloudLogoutBtn">Logout Firestore</button><button class="btn ghost" id="cloudSetupBtn">Ganti Firebase Config</button></div></div></div><div class="card"><div class="cardhead"><h2>Pulihkan Baseline</h2><span class="tag">Tindakan permanen</span></div><div class="alert">Reset akan menimpa data Firestore akun ini dan mengembalikan seluruh data ke baseline yang dibawa file HTML.</div><button class="btn danger" id="resetSeed">Reset Data Firestore ke Awal</button></div>`;document.getElementById('cloudLogoutBtn').onclick=()=>cloudLogout();document.getElementById('cloudSetupBtn').onclick=()=>showCloudSetup();document.getElementById('exportJson').onclick=()=>download(`keuangan-keluarga-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2));document.getElementById('exportCsv').onclick=()=>{const cols=['year','month','section','category','component','budget','actual','recurring','source','sourceRow','note'];const rows=[cols.join(','),...state.budget.map(r=>cols.map(k=>csvEscape(r[k])).join(','))];download('budget-keuangan-2026-2030.csv','\uFEFF'+rows.join('\n'),'text/csv;charset=utf-8')};document.getElementById('importJson').onchange=e=>{const f=e.target.files[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{try{const x=JSON.parse(reader.result);if(!x.budget||!x.categories)throw new Error('Format tidak dikenali');state=x;saveState();alert('Backup berhasil diimpor.');renderBackup()}catch(err){alert('Gagal import: '+err.message)}};reader.readAsText(f)};document.getElementById('resetSeed').onclick=()=>{if(confirm('Yakin reset semua perubahan ke data awal?')){state=clone(SEED);saveState();renderBackup()}}}
initFirestoreApp();
